INSERT INTO organizations (code,name,kind,locality) VALUES
('tl-ubnd','Ủy ban nhân dân phường Từ Liêm','UBND','Phường Từ Liêm, thành phố Hà Nội'),
('tl-hdnd','Hội đồng nhân dân phường Từ Liêm','HDND','Phường Từ Liêm, thành phố Hà Nội')
INSERT INTO departments (code,name,kind,assignment_note) VALUES
('vp','Văn phòng HĐND và UBND','Phòng chuyên môn / bộ phận văn thư, tổng hợp','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('nv','Phòng Nội vụ - Tư pháp','Phòng chuyên môn','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('kt','Phòng Kinh tế','Phòng chuyên môn','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('ht','Phòng Hạ tầng - Nông nghiệp và Môi trường','Phòng chuyên môn','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('vx','Phòng Văn hóa - Xã hội','Phòng chuyên môn','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('mc','Điểm Phục vụ hành chính công / đơn vị giải quyết','Đầu mối liên thông, không gán là phòng chuyên môn','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('qp','Ban Chỉ huy quân sự / Công an phối hợp UBND','Đơn vị phối hợp; chỉ tiếp nhận hồ sơ trong phạm vi được giao','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('tt','Thường trực HĐND','Chủ thể hoạt động HĐND; Văn phòng phục vụ lưu hồ sơ','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('bkt','Ban Kinh tế - Ngân sách HĐND','Ban của HĐND, khác Phòng Kinh tế thuộc UBND','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('bvx','Ban Văn hóa - Xã hội HĐND','Ban của HĐND, khác Phòng Văn hóa - Xã hội thuộc UBND','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát'),
('db','Tổ đại biểu / đại biểu HĐND','Chủ thể hoạt động HĐND; Văn phòng hỗ trợ','Đề xuất; xác nhận theo phân công hiện hành khi khảo sát')
