INSERT INTO work_groups (code,organization_code,department_code,title,responsibility,filing_rule,business_fields) VALUES
('U01','tl-ubnd','vp','Công văn, quyết định, thông báo và sổ đăng ký','Các phòng chuyên môn xử lý nội dung; văn thư quản lý đăng ký và bản lưu.','Sổ đăng ký theo năm; tài liệu đồng thời liên kết với hồ sơ công việc gốc, không gom mọi công văn thành một hồ sơ.','Số đến/đi; ngày nhận/phát hành; nơi gửi/nhận; số, ký hiệu; trích yếu; người ký; hạn xử lý.'),
('U02','tl-ubnd','vp','Chỉ đạo, điều hành và hội nghị UBND','Lãnh đạo UBND và phòng chuyên môn cung cấp báo cáo, xác nhận kết quả.','Theo chương trình, cuộc họp hoặc vụ việc; giữ liên kết tài liệu trước, trong và sau cuộc họp.','Kỳ báo cáo; cuộc họp; ngày họp; nhiệm vụ; đơn vị thực hiện; thời hạn; số văn bản kết luận.'),
('U03','tl-ubnd','vp','Văn thư, lưu trữ và bàn giao sau sắp xếp','Mỗi phòng lập hồ sơ công việc; đầu mối lưu trữ nhận bàn giao theo phân công.','Giữ nguyên nguồn gốc và niên đại trước sắp xếp; lưu riêng đơn vị đang quản lý, không đổi tên cơ quan ban hành cũ thành cơ quan mới.','Cơ quan hình thành; đơn vị giao/nhận; phông; thời gian tài liệu; mã hồ sơ; số tờ; thời hạn lưu trữ; vị trí hộp/kệ.'),
('U04','tl-ubnd','vp','Tiếp công dân, đơn thư và xử lý vụ việc','Đề xuất Văn phòng tổng hợp; phòng theo lĩnh vực chủ trì xác minh theo giao nhiệm vụ; phối hợp Nội vụ - Tư pháp.','Theo vụ việc và quá trình giải quyết; hạn chế quyền truy cập thông tin người gửi, nhất là hồ sơ tố cáo.','Mã vụ việc; loại đơn; người gửi; ngày nhận; nội dung; đơn vị xử lý; hạn; kết quả; liên kết đơn lặp.'),
('U05','tl-ubnd','nv','Tổ chức bộ máy, cán bộ và nhân sự','Văn phòng, các phòng sử dụng nhân sự; kế toán đối chiếu chế độ chi trả.','Theo từng cán bộ hoặc từng đề án tổ chức; dữ liệu nhân sự có quyền xem riêng.','Mã cán bộ; đơn vị; chức danh; quyết định; ngày hiệu lực; bậc/hệ số lương nếu có.'),
('U06','tl-ubnd','nv','Thi đua, khen thưởng và kỷ luật','Đơn vị đề nghị; hội đồng và người có thẩm quyền xem xét.','Tách hồ sơ khen thưởng và hồ sơ kỷ luật; quyền khai thác theo nội dung.','Đợt/năm; cá nhân/tập thể; hình thức; số quyết định; ngày hiệu lực.'),
('U07','tl-ubnd','nv','Cải cách hành chính, công vụ và tổ chức bầu cử','Văn phòng, cơ quan bầu cử, các phòng và tổ dân phố; phân biệt với hồ sơ hoạt động đại biểu HĐND.','Theo nhiệm vụ hoặc kỳ bầu cử. Danh sách cá nhân chỉ nhập khi nằm trong phạm vi được phép số hóa.','Năm; đợt kiểm tra/bầu cử; đơn vị/tổ bầu cử; mốc thời gian; số quyết định; kết quả.'),
('U08','tl-ubnd','nv','Hộ tịch','Đầu mối tiếp nhận TTHC; hệ thống hộ tịch chuyên ngành và cơ quan có thẩm quyền liên quan.','Theo loại việc, năm và số đăng ký; quét sổ bằng thiết bị phù hợp, đối chiếu dữ liệu hộ tịch đã có.','Loại việc; số/quyển đăng ký; ngày đăng ký; họ tên; ngày sinh; quan hệ; số trích lục; định danh chỉ khi cần.'),
('U09','tl-ubnd','nv','Chứng thực','Đầu mối tiếp nhận và cán bộ thực hiện chứng thực.','Theo sổ, năm và số chứng thực; quản lý riêng giấy tờ định danh, bản sao và bản lưu.','Loại chứng thực; số sổ; ngày thực hiện; người yêu cầu; người ký chứng thực; loại giấy tờ.'),
('U10','tl-ubnd','nv','Pháp luật, hòa giải và xử lý vi phạm hành chính','Phòng chuyên môn giữ hồ sơ xử phạt theo lĩnh vực; Nội vụ - Tư pháp đề xuất đầu mối tổng hợp pháp lý.','Tách hồ sơ xây dựng pháp luật, hòa giải và từng vụ xử lý; không tự kết luận thẩm quyền từ tên văn bản.','Loại nhiệm vụ; vụ việc; văn bản liên quan; lĩnh vực; ngày; kết quả hòa giải/xử lý.'),
('U11','tl-ubnd','kt','Ngân sách, kế toán và quyết toán','Kế toán, chủ tài khoản và đơn vị sử dụng ngân sách; xác nhận nơi giữ chứng từ gốc.','Theo kỳ kế toán, nguồn kinh phí và bộ chứng từ; số tiền phải đối chiếu ảnh gốc trước duyệt.','Năm/kỳ; nguồn kinh phí; mục/tiểu mục; số chứng từ; ngày; đối tượng; số tiền; dự án nếu có.'),
('U12','tl-ubnd','kt','Tài sản công, mua sắm và hợp đồng','Văn phòng, đơn vị sử dụng tài sản; chủ đầu tư hoặc bên mời thầu theo phân công.','Theo tài sản hoặc gói mua sắm; liên kết hợp đồng với nghiệm thu, thanh toán và bảo hành.','Mã tài sản/gói thầu; hợp đồng; nhà cung cấp; giá trị; ngày nghiệm thu; đơn vị sử dụng.'),
('U13','tl-ubnd','kt','Kế hoạch phát triển và đầu tư công','Ban quản lý dự án và Phòng Hạ tầng - Nông nghiệp và Môi trường; giữ đúng cơ quan tạo lập từng tài liệu.','Theo dự án và giai đoạn; bản vẽ khổ lớn, bảng tính, phụ lục được liên kết thành phần riêng.','Mã dự án; tên dự án; chủ đầu tư; nguồn vốn; tổng mức; giai đoạn; tiến độ; số quyết định.'),
('U14','tl-ubnd','kt','Hộ kinh doanh, thương mại và dịch vụ','Đầu mối tiếp nhận TTHC, cơ quan thuế và đơn vị chuyên ngành; không nhập thay toàn bộ cơ sở dữ liệu thuế.','Theo cơ sở hoặc vụ việc; đối chiếu hệ thống đăng ký sẵn có, không nhân bản dữ liệu không cần thiết.','Mã hồ sơ/đăng ký; tên cơ sở; chủ hộ; địa điểm; ngành nghề; trạng thái; ngày cấp/thay đổi.'),
('U15','tl-ubnd','ht','Đất đai và hồ sơ địa chính','Cơ quan đăng ký đất đai; điểm tiếp nhận; tổ dân phố và các bên liên quan.','Theo hồ sơ/thửa và lịch sử biến động; lưu cơ quan ban hành cũ, không dùng địa chỉ hiện tại để ghi đè nguồn gốc.','Số thửa đất; tờ bản đồ; địa chỉ; diện tích và đơn vị đo; người sử dụng; số giấy chứng nhận; loại biến động.'),
('U16','tl-ubnd','ht','Thu hồi đất, bồi thường và giải phóng mặt bằng','Ban quản lý dự án, đơn vị thực hiện bồi thường, Phòng Kinh tế và cơ quan chuyên ngành.','Theo dự án → đối tượng → đợt xử lý; bảng nhiều trang giữ cấu trúc hàng/cột, kiểm tra số tiền từng dòng.','Dự án; hộ/tổ chức; thửa đất; diện tích thu hồi; loại tài sản; khoản bồi thường; quyết định; đợt chi trả.'),
('U17','tl-ubnd','ht','Quy hoạch, xây dựng và trật tự xây dựng','Đơn vị chuyên ngành, chủ đầu tư, chủ công trình và đầu mối tiếp nhận.','Theo công trình/vụ việc; tách bản vẽ và ảnh hiện trạng khỏi văn bản nhưng giữ liên kết.','Địa chỉ công trình; chủ đầu tư; số phép; quy mô; thửa đất; vi phạm; thời hạn khắc phục.'),
('U18','tl-ubnd','ht','Hạ tầng đô thị, giao thông và dịch vụ công ích','Ban quản lý dự án, đơn vị vận hành, Phòng Kinh tế và tổ dân phố.','Theo công trình, tuyến hoặc hợp đồng; ảnh, bản đồ và biên bản khối lượng là thành phần hồ sơ.','Tuyến/vị trí; mã công trình; loại hạ tầng; khối lượng; đơn vị thực hiện; thời gian; nghiệm thu.'),
('U19','tl-ubnd','ht','Môi trường, nước và chất thải','Cơ quan chuyên ngành, đơn vị dịch vụ và chủ cơ sở.','Theo cơ sở/vụ việc; giữ đơn vị đo, phương pháp và đơn vị phát hành kết quả xét nghiệm/quan trắc.','Tên cơ sở; địa điểm; nguồn thải; chỉ tiêu đo; ngày kiểm tra; kết quả; thời hạn xử lý.'),
('U20','tl-ubnd','ht','Nông nghiệp, thủy lợi và phòng chống thiên tai','Đơn vị chuyên ngành, ban chỉ huy liên quan, tổ dân phố; chỉ đưa vào danh mục khi có hồ sơ thực tế.','Theo vụ việc hoặc đợt thiên tai; tài liệu thống kê và quyết định hỗ trợ cần đối chiếu.','Địa bàn; đợt/sự kiện; đối tượng; diện tích/số lượng; thiệt hại; mức hỗ trợ; thời gian.'),
('U21','tl-ubnd','vx','Giáo dục và đào tạo','Trường học, cơ quan giáo dục và các đầu mối liên quan; không mặc nhiên thu toàn bộ học bạ của trường.','Theo năm học, nhiệm vụ hoặc cơ sở; danh sách trẻ em/học sinh phân quyền riêng.','Năm học; trường/cơ sở; loại nhiệm vụ; đối tượng chính sách; số quyết định; kỳ hỗ trợ.'),
('U22','tl-ubnd','vx','Y tế, dân số và an toàn thực phẩm','Trạm y tế, cơ quan chuyên ngành và đoàn kiểm tra; hồ sơ bệnh án không mặc nhiên thuộc kho UBND.','Theo đợt/cơ sở/vụ việc; giới hạn dữ liệu sức khỏe cá nhân theo nhu cầu và quyền được giao.','Cơ sở; địa điểm; đợt kiểm tra/dịch; chỉ tiêu; kết quả; số quyết định; thời hạn.'),
('U23','tl-ubnd','vx','Văn hóa, thể thao, thông tin và di tích','Tổ dân phố, đơn vị văn hóa, cơ quan chuyên ngành; xác nhận đầu mối với từng nhiệm vụ tín ngưỡng, tôn giáo nếu phát sinh.','Theo sự kiện, cơ sở hoặc năm xét danh hiệu; ảnh và phụ lục là thành phần đính kèm.','Tên hoạt động/cơ sở; địa điểm; thời gian; di tích/danh hiệu; quyết định; kết quả kiểm tra.'),
('U24','tl-ubnd','vx','An sinh, bảo trợ xã hội, giảm nghèo và trẻ em','Đầu mối tiếp nhận, đơn vị chi trả, tổ dân phố và cơ quan liên quan; đối chiếu phân công sau tổ chức lại.','Theo đối tượng/đợt hỗ trợ; tách quyền truy cập dữ liệu trẻ em, khuyết tật và hoàn cảnh cá nhân.','Mã đối tượng; diện trợ giúp; thời điểm hưởng; mức; kỳ chi trả; quyết định; tình trạng hồ sơ.'),
('U25','tl-ubnd','nv','Người có công, lao động và chính sách việc làm','Đề xuất đầu mối Nội vụ - Tư pháp cho lĩnh vực nội vụ/lao động; phối hợp Văn hóa - Xã hội và đơn vị chuyên ngành, cần xác nhận phân công cụ thể.','Theo đối tượng và chính sách; không mặc nhiên sao chép hồ sơ bảo hiểm do cơ quan BHXH quản lý.','Loại chính sách; mã đối tượng; quyết định; kỳ hưởng; mức hỗ trợ; trạng thái chuyển xử lý.'),
('U26','tl-ubnd','vx','Khoa học, công nghệ, thông tin và chuyển đổi số','Văn phòng, đơn vị quản trị CNTT, Phòng Kinh tế và nhà cung cấp theo phân công.','Theo hệ thống/dự án; không đưa mật khẩu, khóa bí mật hay thông tin xác thực vào chỉ mục OCR.','Hệ thống/dự án; phiên bản; đơn vị phụ trách; kỳ báo cáo; thời điểm sự cố; biên bản nghiệm thu.'),
('U27','tl-ubnd','mc','Hồ sơ tiếp nhận và trả kết quả TTHC','Điểm Phục vụ hành chính công phối hợp phòng giải quyết; là luồng liên thông, không mặc định là một phòng thuộc UBND phường.','Ưu tiên đối soát dữ liệu hệ thống một cửa; liên kết về hồ sơ hộ tịch, đất đai… tương ứng để tránh quét và lưu trùng.','Mã hồ sơ một cửa; mã TTHC; người nộp; ngày nhận/hẹn/trả; cơ quan xử lý; trạng thái; kết quả.'),
('U28','tl-ubnd','qp','Quốc phòng, an ninh và phòng cháy phối hợp UBND','Ban Chỉ huy quân sự, Công an và đơn vị liên quan xác nhận phạm vi. Không coi các đơn vị này là phòng chuyên môn của UBND.','Chỉ tiếp nhận tài liệu được phép đưa vào dự án; hồ sơ nghiệp vụ chuyên ngành và tài liệu mật phải có phạm vi, môi trường riêng.','Loại nhiệm vụ; đợt/năm; đơn vị hình thành; địa bàn; số văn bản; chế độ truy cập đã xác định.'),
('H01','tl-hdnd','tt','Tổ chức kỳ họp HĐND','Văn phòng HĐND và UBND phục vụ; các Ban thẩm tra; cơ quan trình chịu trách nhiệm tài liệu của mình.','Một kỳ họp có nhiều nội dung; gom theo kỳ họp → nội dung → từng tài liệu, không gộp mọi trang thành một văn bản.','Khóa; nhiệm kỳ; số/kỳ họp; ngày; nội dung; cơ quan trình; số tờ trình; nghị quyết liên quan.'),
('H02','tl-hdnd','tt','Ban hành và theo dõi nghị quyết','Ban thẩm tra theo lĩnh vực; UBND và đơn vị được giao thực hiện; Văn phòng lưu hồ sơ phục vụ.','Theo nghị quyết và chuỗi dự thảo → thẩm tra → thông qua → thực hiện; cơ quan ban hành HĐND tách với cơ quan trình UBND.','Số, ký hiệu; ngày; trích yếu; khóa/kỳ họp; người ký; ngày hiệu lực nếu nêu; văn bản bị sửa/thay thế.'),
('H03','tl-hdnd','bkt','Thẩm tra kinh tế, ngân sách và đầu tư','Phòng Kinh tế, phòng phụ trách hạ tầng, UBND và đơn vị trình; Ban HĐND là đầu mối thẩm tra.','Theo từng nội dung thẩm tra; Ban Kinh tế - Ngân sách và Phòng Kinh tế là hai chủ thể khác nhau.','Kỳ họp; loại báo cáo; năm/kỳ ngân sách; dự án; chỉ tiêu; số tiền; kết luận/kiến nghị.'),
('H04','tl-hdnd','bvx','Thẩm tra văn hóa, xã hội và lĩnh vực được giao','Phòng Văn hóa - Xã hội, Nội vụ - Tư pháp và đơn vị trình tùy lĩnh vực.','Theo nội dung được giao thẩm tra; phân biệt Ban Văn hóa - Xã hội HĐND với phòng cùng lĩnh vực của UBND.','Kỳ họp; lĩnh vực; đối tượng chính sách; chỉ tiêu; nội dung thẩm tra; kiến nghị; đơn vị trả lời.'),
('H05','tl-hdnd','tt','Giám sát, khảo sát và theo dõi kiến nghị','Chủ thể thực tế có thể là Thường trực hoặc một Ban HĐND theo quyết định đoàn; Văn phòng hỗ trợ.','Theo đợt/chuyên đề; giữ danh sách kiến nghị và liên kết từng văn bản trả lời, không chỉ lưu báo cáo tổng kết.','Tên/đợt giám sát; chủ thể; đơn vị chịu giám sát; thời gian; kiến nghị; hạn; kết quả.'),
('H06','tl-hdnd','tt','Chất vấn, giải trình và trả lời','Đại biểu/Tổ đại biểu đề nghị; UBND và phòng, đơn vị trả lời theo nội dung.','Theo phiên và từng vấn đề; văn bản trả lời phải gắn đúng câu hỏi, giữ cơ quan phát hành gốc.','Người/đơn vị chất vấn; nội dung; người trả lời; ngày; cam kết; hạn; trạng thái theo dõi.'),
('H07','tl-hdnd','db','Tiếp xúc cử tri và kiến nghị cử tri','Thường trực HĐND, MTTQ phối hợp tổ chức; cơ quan được chuyển xử lý trả lời.','Theo đợt và từng kiến nghị; một văn bản trả lời nhiều kiến nghị cần liên kết nhiều mục.','Đợt trước/sau kỳ họp; tổ đại biểu; địa bàn; mã kiến nghị; nội dung; nơi xử lý; hạn; kết quả.'),
('H08','tl-hdnd','tt','Tiếp công dân và đơn thư gửi HĐND','Đại biểu, Văn phòng và cơ quan có trách nhiệm giải quyết; HĐND theo dõi/giám sát theo nhiệm vụ.','Giữ hồ sơ tiếp nhận tại HĐND và liên kết hồ sơ xử lý của UBND; không gộp hai chủ thể thành một.','Mã đơn/vụ việc; người gửi; ngày nhận; nơi chuyển; số văn bản trả lời; tình trạng.'),
('H09','tl-hdnd','db','Đại biểu, Tổ đại biểu và công tác nhân sự HĐND','Thường trực HĐND, Văn phòng; Nội vụ - Tư pháp phối hợp hồ sơ tổ chức, bầu cử theo phân công.','Theo nhiệm kỳ và đại biểu/Tổ; tách hồ sơ hoạt động HĐND khỏi bộ hồ sơ tổ chức bầu cử.','Khóa; nhiệm kỳ; đại biểu; Tổ/Ban; chức danh; quyết định; thời gian hiệu lực.'),
('H10','tl-hdnd','tt','Chương trình công tác, phối hợp và tổng kết nhiệm kỳ','Các Ban, Tổ đại biểu, Văn phòng và cơ quan phối hợp.','Theo năm/nhiệm kỳ và nhiệm vụ; lưu cả phụ lục thống kê, danh mục hồ sơ bàn giao.','Khóa/nhiệm kỳ; kỳ báo cáo; chương trình; chủ thể; cơ quan phối hợp; ngày bàn giao.')
